      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-arpeggio-from-3rd-bebop",
      "narrative": "For min7 in bebop context, Larsen prescribes: 'Playing an arpeggio from the 3rd of a chord is a useful device to produce characteristic bebop lines.' This is a named and endorsed bebop substitution principle. Chapter 2, p. 36.",
      "source_principle_ids": [
        "jens-larsen:modern-jazz-guitar-concepts:harmonic-substitution-lattice"
      ],
      "source_work_id": "modern-jazz-guitar-concepts",
