      "granularity_name": "other"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-chromatic-approach-to-third",
      "narrative": "Over a min7 II chord, Larsen prescribes a chromatic bebop approach to the third: 'Over a II chord, a common bebop device is to approach the third chromatically from a whole step above. In the example below this is the chromatic descent from C to Bb.' Chapter 3, p. 50.",
      "source_principle_ids": [
        "jens-larsen:modern-jazz-guitar-concepts:chromatic-enclosure-system"
      ],
      "source_work_id": "modern-jazz-guitar-concepts",
      "references": [
