      "provenance": "extracted",
      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "min7",
      "function_role": "ii-chord-5th-arpeggio-voice-leading-to-v",
      "narrative": "For min7 as II chord, Larsen prescribes arpeggiation from the 5th as a voice-leading device: 'Playing an arpeggio from the 5th of the II chord is a fantastic way to target the third of the V chord that follows it. To the ears, it sounds like a suspended chord, but without moving very far from the key.' Chapter 3, p. 49.",
      "source_principle_ids": [
        "jens-larsen:modern-jazz-guitar-concepts:harmonic-substitution-lattice"
      ],
      "source_work_id": "modern-jazz-guitar-concepts",
