          "citation": "chapter 4 p. 53-54"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7alt",
      "function_role": "altered-dominant-four-note-enclosure-to-suspend-3rd",
      "narrative": "For dom7alt (applied to the preceding tonic Fm7 leading into Bb7alt), Larsen prescribes four-note chromatic enclosure to delay arrival: 'In Example 4o the purpose of the enclosure is to suspend the 3rd of the Fm7 chord until beat 3, before the line continues with an Abmaj7 arpeggio.' The enclosure suspends and then releases the target chord tone. Chapter 4, p. 61.",
      "source_principle_ids": [
        "jens-larsen:modern-jazz-guitar-concepts:chromatic-enclosure-system"
      ],
      "source_work_id": "modern-jazz-guitar-concepts",
      "references": [
        {
          "source": "modern-jazz-guitar-concepts",
          "citation": "chapter 4 p. 61"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7alt",
      "function_role": "altered-dominant-dual-analysis",
      "narrative": "For dom7alt lines, Larsen explicitly endorses multiple simultaneous valid analyses: 'The F7 altered line can be analysed in two ways: an Ebm7b5 arpeggio over the whole bar, or a Gbm triad for the first half of the bar and an Ebm7b5 arpeggio inversion for the second half.' Students should internalize the system rather than fix on one reading. Chapter 6, p. 82.",
      "source_principle_ids": [
